/** The provider contract is plain text only. Sanitizing active markup after
 * generation would hide a model-contract breach, so raw output is rejected
 * before any cleanup or HTML assembly. */
export function validateDiscoveryPlainTextCandidate(text: string): string[] {
  const raw = String(text || "");
  const normalizedRaw = raw.normalize("NFKC").replace(/[\u200B-\u200D\u2060\uFEFF]/g, "");
  const errors: string[] = [];
  if (/<!--|-->|<!doctype|<\?xml|<\/?[a-z][^>]*>/i.test(normalizedRaw)) errors.push("raw_html");
  if (/(?:[a-z][a-z0-9+.-]*:|\/\/|www\.)\S*|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|io|fr|eu|co|dev|app|info|biz|me|ai)\b/i.test(normalizedRaw)
    || /\b[a-z0-9-]+\s+(?:dot|point)\s+(?:com|net|org|io|fr|eu|co|dev|app|info|biz|me|ai)\b/i.test(normalizedRaw)) {
    errors.push("external_url");
  }
  const compact = normalizedRaw.normalize("NFKD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[\u0406\u0456\u04C0\u0399\u03B9]/g, "I")
    .replace(/[\u041E\u043E\u039F\u03BF]/g, "O")
    .replace(/[\u0421\u0441]/g, "C")
    .replace(/[^a-z0-9]+/gi, "").toUpperCase();
  const preReviewPromoCode = ["DISCOVERY", "20"].join("");
  const promoSkeleton = compact
    .replace(/DISC0VERY/g, "DISCOVERY")
    .replace(/DISCOVERY2O/g, preReviewPromoCode);
  if (promoSkeleton.includes(preReviewPromoCode)) {
    errors.push("pre_review_promo_code");
  }
  if (/^\s{0,3}#{1,6}\s|^\s*(?:[-*+>]\s+|\d{1,3}[.)]\s+)|^\s*\|.+\|\s*$|^\s*(?:={3,}|-{3,})\s*$|(?:\*\*|__|~~)[^\n]+(?:\*\*|__|~~)|(?:^|\s)[*_][^\n*_]+[*_](?:\s|$)|`{1,3}[^`]+`{1,3}|\[[^\]]+\]\([^\)]+\)/m.test(normalizedRaw)) {
    errors.push("markdown");
  }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(normalizedRaw)) errors.push("control_character");
  return [...new Set(errors)];
}

/** Provider prose explains mechanisms only. Personal values, quantities,
 * frequencies, scores and severity labels are rendered by deterministic code. */
export function validateDiscoveryMechanismProse(text: string): string[] {
  const normalized = normalizeDiscoveryFactText(String(text || ""));
  const errors: string[] = [];
  if (/\d/.test(normalized)) errors.push("provider_numeric_value");
  if (/\b(?:deux|trois|quatre|cinq|six|sept|huit|neuf|dix|onze|douze|treize|quatorze|quinze|seize|vingt)\b/.test(normalized)) {
    errors.push("provider_number_word");
  }
  if (/\b(?:un|une)\s+(?:litres?|cafes?|tasses?|verres?|heures?|seances?)\b/.test(normalized)) {
    errors.push("provider_quantity_word");
  }
  if (/\b(?:jamais|rarement|parfois|souvent|toujours|quotidien(?:ne)?|chaque\s+(?:jour|nuit|semaine))\b/.test(normalized)) {
    errors.push("provider_frequency_value");
  }
  if (/\bcritique(?:s)?\b|\bcritical\b/.test(normalized)) errors.push("provider_severity_label");
  if (/\b(?:tu|toi|ton|ta|tes|te|t'|vous|votre|vos)\b/.test(normalized)) {
    errors.push("provider_personalized_claim");
  }
  if (/\b(?:profil|personne|individu|chez|declaree?s?|observee?s?|montre|presente)\b/.test(normalized)) {
    errors.push("provider_profile_claim");
  }
  if (/\b(?:mauvais(?:e)?|difficile|eleve(?:e)?|faible|irregulier(?:e)?|stagnation|regression|excellente?|insuffisant(?:e)?|fragmente(?:e)?)\b/.test(normalized)) {
    errors.push("provider_state_assertion");
  }
  return [...new Set(errors)];
}

/**
 * Provider prose is intentionally generic. Small wording slips such as a
 * counted set of mechanisms or a reviewed generic state must not force a paid
 * retry when a complete phrase-level rewrite preserves the mechanism. This
 * pass is deliberately narrow: unknown states, personal pronouns, profile
 * claims and source attributions remain intact for fail-closed validation.
 */
export function sanitizeDiscoveryMechanismProse(text: string): string {
  const numberWord = "deux|trois|quatre|cinq|six|sept|huit|neuf|dix|onze|douze|treize|quatorze|quinze|seize|vingt";
  const personalOrProfileClaim = /\b(?:tu|toi|ton|ta|tes|te|t'|vous|votre|vos|profil|personne|individu|chez|declaree?s?|observee?s?|montre|presente)\b/;
  const copularState = /^(.*?)\s+(?:(?:peut|pourrait)\s+[eê]tre|est|reste|devient)\s+(mauvais(?:e)?|difficile|[eé]lev[eé](?:e)?|faible|irr[eé]gulier(?:e)?|excellent(?:e)?|insuffisant(?:e)?|fragment[eé](?:e)?)([.!?])$/iu;

  const rewriteGenericStateSentence = (sentence: string): string => {
    const leading = sentence.match(/^\s*/)?.[0] || "";
    const trailing = sentence.match(/\s*$/)?.[0] || "";
    const core = sentence.trim();
    if (!core) return sentence;
    const normalized = normalizeDiscoveryFactText(core);
    // Never sanitize evidence that the provider attempted to personalize.
    // Leaving it byte-for-byte intact guarantees the strict validator rejects
    // both the personal claim and any accompanying state assertion.
    if (personalOrProfileClaim.test(normalized)) return sentence;

    const stateMatch = core.match(copularState);
    if (!stateMatch) return sentence;
    const subject = stateMatch[1].trim();
    const state = normalizeDiscoveryFactText(stateMatch[2]);
    const punctuation = stateMatch[3];
    const normalizedSubject = normalizeDiscoveryFactText(subject);
    let replacement: string | null = null;
    if (/^(?:la|une) recuperation$/.test(normalizedSubject) && state === "insuffisante") {
      replacement = "Un déséquilibre entre charge et récupération peut limiter les ressources adaptatives";
    } else if (/^(?:la|une) charge$/.test(normalizedSubject) && state === "elevee") {
      replacement = `${subject} mobilise des ressources adaptatives et influence la récupération`;
    } else if (/^(?:la|une) contrainte$/.test(normalizedSubject) && state === "elevee") {
      replacement = `${subject} mobilise des ressources adaptatives et influence la récupération`;
    } else if (/^(?:le|un) signal$/.test(normalizedSubject) && state === "irregulier") {
      replacement = "La régularité du signal influence la stabilité des mécanismes";
    } else if (/^(?:le|un) rythme$/.test(normalizedSubject) && state === "irregulier") {
      replacement = "La régularité du rythme influence la stabilité des mécanismes";
    } else if (/^(?:le|un) sommeil$/.test(normalizedSubject) && state === "fragmente") {
      replacement = "La continuité du sommeil influence la récupération et la régulation énergétique";
    } else if (/^(?:le|un) stress$/.test(normalizedSubject) && state === "faible") {
      replacement = "La régulation du stress influence la mobilisation des ressources adaptatives";
    }
    // Unknown subjects have no reviewed semantic template.  Keep the original
    // assertion so the strict gate rejects it instead of risking an inversion.
    if (!replacement) return sentence;
    return `${leading}${replacement}${punctuation}${trailing}`;
  };

  const sanitized = String(text || "").normalize("NFKC")
    .replace(/[^\n.!?]+[.!?]?/gu, (sentence) => {
      let rewritten = rewriteGenericStateSentence(sentence);
      const normalized = normalizeDiscoveryFactText(rewritten);
      if (personalOrProfileClaim.test(normalized)) return rewritten;
      rewritten = rewritten
        // Preserve a natural determiner when the provider needlessly counted
        // a generic group: "les deux dimensions" becomes "les dimensions".
        .replace(new RegExp(`\\b(les|ces|des)\\s+(?:${numberWord})\\s+(?=\\p{L})`, "giu"), "$1 ")
        .replace(/\b(les|ces|des)\s+\d+\s+(?=\p{L})/giu, "$1 ")
        .replace(
          new RegExp(`\\b(${numberWord}|\\d+)\\s+(dimensions?|m[eé]canismes?|axes?|signaux?|facteurs?|variables?|syst[eè]mes?|processus)\\b`, "giu"),
          (_match: string, _count: string, noun: string, offset: number, source: string) => {
            const prefix = source.slice(0, offset);
            const sentenceInitial = !/[\p{L}\p{N}]/u.test(prefix);
            return `${sentenceInitial ? "Plusieurs" : "plusieurs"} ${noun}`;
          },
        )
        // These noun phrases have one exact grammatical, non-personal rewrite.
        // Any other state construction remains untouched and therefore fails
        // validateDiscoveryMechanismProse instead of being silently damaged.
        .replace(/\bcontraintes\s+[eé]lev[eé]es\b/giu, "contraintes exercées")
        .replace(/\bcontrainte\s+[eé]lev[eé]e\b/giu, "contrainte exercée")
        .replace(/[ \t]{2,}/g, " ")
        .replace(/\s+([,.;:!?])/g, "$1");
      return rewritten;
    });

  return normalizeParagraphs(sanitized.trim());
}

function cleanDiscoveryNarrativeProse(text: string): string {
  let cleaned = repairDiscoveryKnownFrenchCorruptions(
    normalizeDiscoveryFrenchSurface(stripInlineHtml(String(text || ""))),
  )
    .replace(/^(En tant qu['’]expert[^.]*\.?\s*)/gi, "")
    .replace(/^(Cette analyse (montre|revele|révèle|demontre|démontre)[^.]*\.?\s*)/gi, "")
    .replace(/^(Je vais (analyser|examiner|etudier|étudier)[^.]*\.?\s*)/gi, "")
    .replace(/^(Voici (mon analyse|l['’]analyse|une analyse)[^.]*\.?\s*)/gi, "")
    .replace(/\u2014/g, ":")
    .replace(/\u2013/g, "-")
    .replace(/\*\*/g, "")
    .replace(/##\s*/g, "")
    .replace(/^\s*[-*]\s+/gm, "")
    .replace(/^\s*\d+\.\s+/gm, "")
    .trim();
  if (hasEnglishMarkers(cleaned, 6)) cleaned = stripEnglishLines(cleaned);
  cleaned = normalizeSingleVoice(cleaned);
  cleaned = stripCitationLines(cleaned);
  cleaned = neutralizeDiscoverySourceAttribution(cleaned);
  cleaned = qualifyDiscoveryMedicalAssertions(cleaned);
  cleaned = repairDiscoveryKnownFrenchCorruptions(cleaned);
  cleaned = normalizeParagraphs(cleaned);
  // Keep the cleanup pipeline idempotent: every transformer above may evolve,
  // but no accentless delivery token can be reintroduced after this final pass.
  return normalizeDiscoveryFrenchSurface(repairDiscoveryKnownFrenchCorruptions(cleaned));
}

export function validateDiscoveryGeneratedNarrative(
  raw: unknown,
  _responses: DiscoveryResponses,
  _safetyPolicy: DiscoverySafetyPolicy,
): DiscoveryGeneratedNarrative {
  return assembleDiscoveryMechanismSelection(validateDiscoveryMechanismSelection(raw));
}

async function generateDiscoveryNarrativeAI(
  responses: DiscoveryResponses,
  scores: DiscoveryAnalysisResult['scoresByDomain'],
  blocages: BlockageAnalysis[],
  knowledge: DiscoveryKnowledgePreflight,
  safetyPolicy: DiscoverySafetyPolicy,
  costBudgetAuditId?: string,
  costBudgetGenerationToken?: string,
  costBudgetFenceToken?: string | null,
  costBudgetAllowLegacy?: boolean,
  costBudgetBatchId?: string,
  costBudgetBatchLockToken?: string,
): Promise<DiscoveryGeneratedNarrative> {
  assertDiscoveryUnifiedGenerationEnabled();
  if (!costBudgetAuditId) {
    throw new Error("DISCOVERY_DURABLE_COST_BUDGET_REQUIRED");
  }
  const hasGenericOwnership = Boolean(costBudgetGenerationToken);
  const hasBatchOwnership = Boolean(costBudgetBatchId && costBudgetBatchLockToken);
  if (hasGenericOwnership === hasBatchOwnership) {
    throw new Error("DISCOVERY_PROVIDER_OWNERSHIP_REQUIRED");
  }
  void scores;
  void blocages;
  void safetyPolicy;
  const mechanismScopes = buildDiscoveryQuestionnaireFacts({});
  const instructionBlock = DISCOVERY_PREMIUM_DOMAINS
    .map((domain) => `${domain}: ${SECTION_INSTRUCTIONS[domain]}`)
    .join("\n");
  const knowledgeBlock = [
    `synthese:\n${assertDiscoveryPremiumKnowledgeContext(knowledge.synthesis, "synthesis")}`,
    ...DISCOVERY_PREMIUM_DOMAINS.map((domain) => (
      `${domain}:\n${assertDiscoveryPremiumKnowledgeContext(knowledge.domains[domain], `section ${domain}`)}`
    )),
  ].join("\n\n=== DOMAINE SUIVANT ===\n\n");

  const input = `MISSION UNIQUE: selectionner uniquement des identifiants de mecanismes approuves pour un Discovery Scan.

Aucune donnee personnelle, reponse, identite, score, priorite ou information medicale ne t'est fournie. N'en deduis aucune. La personnalisation factuelle sera ajoutee apres ton appel par un moteur deterministe.

PERIMETRES DE MECANISMES AUTORISES:
${mechanismScopes}

CONSIGNES PAR DOMAINE:
${instructionBlock}

BASE SCIENTIFIQUE INTERNE. Elle sert seulement a expliquer les mecanismes pertinents. Ne cite aucun titre, auteur, media, marque ou source. Ignore tout exemple hors profil:
${knowledgeBlock}

CONTRAT DE SORTIE FERME:
catalogVersion doit etre exactement ${DISCOVERY_MECHANISM_CATALOG_VERSION}.
catalogSha256 doit etre exactement ${DISCOVERY_MECHANISM_CATALOG_SHA256}.
synthesisDomains contient exactement quatre domaines distincts parmi: ${DISCOVERY_PREMIUM_DOMAINS.join(", ")}.
sections contient exactement les huit domaines. Chaque domaine contient exactement deux identifiants distincts choisis dans sa liste:
${DISCOVERY_PREMIUM_DOMAINS.map((domain) => `${domain}: ${DISCOVERY_MECHANISM_CATALOG_IDS[domain].join(", ")}`).join("\n")}
Ne redige aucun texte. Ne renvoie aucun champ libre, commentaire, explication, nom, valeur ou propriete supplementaire. Le moteur local assemble toute la prose depuis le catalogue scelle.`;

  if (input.length > DISCOVERY_UNIFIED_MAX_INPUT_CHARS) {
    throw new Error(
      `Discovery unified prompt exceeds budget: ${input.length}/${DISCOVERY_UNIFIED_MAX_INPUT_CHARS} chars`,
    );
  }

  const response = await withTimeout(
    runOpenAIText({
      profile: "discovery",
      instructions: `Tu selectionnes uniquement des identifiants enum dans le JSON strict demande. Tu ne rediges aucune prose et n'ajoutes aucune propriete.`,
      input,
      safetyId: `discovery:${costBudgetAuditId}`,
      schema: DISCOVERY_UNIFIED_SCHEMA as unknown as Record<string, unknown>,
      schemaName: "discovery_unified_report_v1",
      maxOutputTokens: DISCOVERY_UNIFIED_MAX_OUTPUT_TOKENS,
      retries: 1,
      label: "discovery-unified-report",
      costBudget: {
        product: "discovery",
        orderId: costBudgetAuditId,
        estimatedCostUsd: DISCOVERY_UNIFIED_MAX_ESTIMATED_COST_USD,
        discoveryGenerationToken: costBudgetGenerationToken,
        discoveryFenceToken: costBudgetFenceToken,
        discoveryAllowLegacy: costBudgetAllowLegacy,
        discoveryBatchId: costBudgetBatchId,
        discoveryBatchLockToken: costBudgetBatchLockToken,
      },
    }),
    DISCOVERY_AI_TIMEOUT_MS,
    "OpenAI unified Discovery report",
  );

  let parsed: unknown;
  try {
    parsed = JSON.parse(response.text);
  } catch (error) {
    throw new DiscoveryRejectedCandidateError({
      providerRaw: response.text,
      responseId: response.responseId,
      model: response.model,
      validationErrors: [`Discovery unified JSON invalid: ${error instanceof Error ? error.message : String(error)}`],
      usage: {
        inputTokens: Number(response.usage?.tokens.inputTokens || 0),
        outputTokens: Number(response.usage?.tokens.outputTokens || 0),
        totalTokens: Number(response.usage?.tokens.totalTokens || 0),
        actualCostUsd: Number(response.usage?.costs.openaiGpt56SolUsd || 0),
      },
    });
  }
  const providerEvidence: DiscoveryProviderEvidence = {
    responseId: response.responseId,
    model: response.model,
    rawCandidate: parsed,
    inputTokens: Number(response.usage?.tokens.inputTokens || 0),
    outputTokens: Number(response.usage?.tokens.outputTokens || 0),
    totalTokens: Number(response.usage?.tokens.totalTokens || 0),
    actualCostUsd: Number(response.usage?.costs.openaiGpt56SolUsd || 0),
    catalogVersion: DISCOVERY_MECHANISM_CATALOG_VERSION,
    catalogSha256: DISCOVERY_MECHANISM_CATALOG_SHA256,
    selectionSha256: discoveryCatalogSelectionSha256(parsed),
  };
  try {
    const generated = validateDiscoveryGeneratedNarrative(parsed, responses, safetyPolicy);
    if (!generated.catalogProvenance
      || generated.catalogProvenance.selectionSha256 !== providerEvidence.selectionSha256) {
      throw new Error("Discovery mechanism selection provenance mismatch");
    }
    generated.catalogProvenance.providerResponseId = response.responseId;
    return { ...generated, providerEvidence };
  } catch (error) {
    const validationErrors = error instanceof Error
      ? [error.message]
      : [String(error)];
    throw new DiscoveryRejectedCandidateError({
      providerRaw: parsed,
      responseId: response.responseId,
      model: response.model,
      validationErrors,
      usage: {
        inputTokens: providerEvidence.inputTokens,
        outputTokens: providerEvidence.outputTokens,
        totalTokens: providerEvidence.totalTokens,
        actualCostUsd: providerEvidence.actualCostUsd,
      },
    });
  }
}

