/**
 * Rebuild a catalogue-backed Discovery report without a provider call.
 *
 * This is deliberately narrower than `analyzeDiscoveryScan`: the only prose
 * accepted here is selected from the immutable catalogue and the selection is
 * accepted only when every provenance hash still binds.  It is intended for
 * forensic replay of a previously completed provider selection.
 */
export function reconstructDiscoveryCatalogReport(input: {
  responses: DiscoveryResponses;
  catalogProvenance: DiscoveryCatalogProvenance;
  expectedProviderResponseId: string;
  generatedAt: string;
}): {
  narrativeReport: ReportData;
  scores: Record<string, number>;
  txt: string;
  html: string;
} {
  const providerResponseId = String(input.expectedProviderResponseId || "").trim();
  const generatedAt = String(input.generatedAt || "").trim();
  if (!providerResponseId) throw new Error("DISCOVERY_CATALOG_REPLAY_PROVIDER_RESPONSE_REQUIRED");
  if (!generatedAt || Number.isNaN(Date.parse(generatedAt))) {
    throw new Error("DISCOVERY_CATALOG_REPLAY_GENERATED_AT_INVALID");
  }
  const questionnaireErrors = validateDiscoveryQuestionnaireContract(input.responses);
  if (questionnaireErrors.length > 0) {
    throw new Error(`DISCOVERY_CATALOG_REPLAY_QUESTIONNAIRE_INVALID:${questionnaireErrors.join("|")}`);
  }

  const provenance = structuredClone(input.catalogProvenance);
  const selection = validateDiscoveryMechanismSelection(provenance?.selection);
  const expectedSelectionSha256 = discoveryCatalogSelectionSha256(selection);
  if (provenance.editorialSourceSha256 !== DISCOVERY_MECHANISM_EDITORIAL_SOURCE_SHA256
    || provenance.catalogVersion !== DISCOVERY_MECHANISM_CATALOG_VERSION
    || provenance.catalogSha256 !== DISCOVERY_MECHANISM_CATALOG_SHA256
    || provenance.selectionSha256 !== expectedSelectionSha256
    || provenance.providerResponseId !== providerResponseId) {
    throw new Error("DISCOVERY_CATALOG_REPLAY_PROVENANCE_MISMATCH");
  }

  const deterministic = calculateDiscoveryDeterministicProfile(input.responses);
  const assembled = assembleDiscoveryMechanismSelection(selection);
  const narrativeReport = convertToNarrativeReport({
    globalScore: deterministic.globalScore,
    scoresByDomain: deterministic.scoresByDomain,
    blocages: deterministic.blocages,
    synthese: assembled.synthesis,
    sectionContents: assembled.sections,
    ctaMessage: buildDiscoveryDeterministicCta(
      deterministic.blocages,
      deterministic.safetyPolicy,
    ),
    knowledgePreflight: { synthesis: "", domains: {} },
    safetyPolicy: deterministic.safetyPolicy,
    questionnaireCoverage: deterministic.questionnaireCoverage,
    catalogProvenance: provenance,
  }, input.responses, { generatedAt });
  const provenanceErrors = validateDiscoveryCatalogReportProvenance(
    narrativeReport,
    providerResponseId,
  );
  if (provenanceErrors.length > 0) {
    throw new Error(`DISCOVERY_CATALOG_REPLAY_REPORT_PROVENANCE_INVALID:${provenanceErrors.join("|")}`);
  }
  const { txt, html } = buildDiscoveryReportAssets(narrativeReport);
  const scores = { ...deterministic.scoresByDomain, global: deterministic.globalScore };
  const persistence = validateDiscoveryPersistenceContract({
    narrativeReport,
    scores,
    txt,
    html,
    responses: input.responses,
  });
  if (!persistence.ok) {
    throw new Error(`DISCOVERY_CATALOG_REPLAY_PERSISTENCE_INVALID:${persistence.errors.join("|")}`);
  }
  return { narrativeReport, scores, txt, html };
}

/**
 * Audits customer-analysis metadata that is persisted but not necessarily
 * rendered in the narrative. Hidden fields must never be a bypass around the
 * same medical-safety contract enforced on visible sections.
 */
export function validateDiscoveryNonRenderedMetadata(metadata: unknown): string[] {
  const text = JSON.stringify(metadata ?? {});
  const normalized = text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const forbidden: Array<[string, RegExp]> = [
    ["mitochondrial_dysfunction", /\bdysfonction(?:nement)?\s+(?:energetique\s+et\s+)?mitochondrial(?:e)?\b/],
    ["metabolic_inflexibility", /\binflexibilite\s+metabolique\b/],
    ["glucose_dependency", /\bdependance\s+au\s+glucose\b|\bincapacite\s+a\s+(?:bruler|utiliser)\s+les\s+graisses\b/],
    ["thyroid_inference", /\bt3\s+libre\b|\bhypothyroidie\b|\bthyroide\s+ralentie\b/],
    ["growth_hormone_inference", /\bgh\s+(?:effondree|diminuee|basse)\b/],
    ["insulin_inference", /\bresistance\s+a\s+l[' ]insuline\b|\bsensibilite\s+a\s+l[' ]insuline\s+(?:basse|diminuee)\b/],
    ["hpa_dysregulation", /\bdysregulation\s+de\s+l[' ]axe\b|\baxe\s+hpa\b.{0,45}\bhyperactivation\b/],
    ["digestive_diagnosis", /\bdysbiose\b|\bhypochlorhydrie\b|\bsibo\b|\bpermeabilite\s+intestinale\b|\bmalabsorption\b/],
  ];
  const errors = forbidden.filter(([, pattern]) => pattern.test(normalized)).map(([label]) => label);
  return [...new Set(errors)];
}

export function validateDiscoveryReportForDelivery(
  report: Partial<ReportData> | null | undefined,
  assets?: { txt?: string | null; html?: string | null },
  nonRenderedMetadata?: unknown,
): { ok: boolean; errors: string[] } {
  const errors: string[] = [];
  const sections = Array.isArray(report?.sections) ? report.sections : [];
  const metrics = Array.isArray(report?.metrics) ? report.metrics : [];
  const stripHtml = (s: string) => String(s ?? "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
  const totalContent = sections.reduce((sum, s) => sum + stripHtml((s as any).content || "").length, 0);
  const weakSections = sections.filter((s) => stripHtml((s as any).content || "").length < 80);
  const txt = String(assets?.txt || "").trim();
  const html = String(assets?.html || "").trim();
  const expectedSectionIds = [
    "intro", "global", "sommeil", "stress", "energie", "digestion",
    "training", "nutrition", "lifestyle", "mindset", "scans", "coaching",
  ];
  const sectionById = new Map(sections.map((section: any) => [String(section?.id || ""), section]));
  const evidence = report?.generationQuality;
  const safetyEvidence = evidence?.safety;
  const safetyPolicy: DiscoverySafetyPolicy = {
    version: 1,
    tcaMode: safetyEvidence?.tcaMode || "none",
    bodyCheckingSignal: safetyEvidence?.bodyCheckingSignal === true,
    restrictiveEatingSignal: false,
    strictEatingSafety: safetyEvidence?.strictEatingSafety === true,
    triggerKeys: [],
  };

  const legacyEvidenceValid = evidence?.version === 1
    && evidence.mode === "premium_ai"
    && evidence.provider === "openai"
    && evidence.synthesis === "ai_validated"
    && evidence.providerRole === undefined;
  const catalogEvidenceValid = evidence?.version === 2
    && evidence.mode === "catalog_selected"
    && evidence.provider === "openai"
    && evidence.providerRole === "selection"
    && evidence.synthesis === "catalog_rendered";
  if ((!legacyEvidenceValid && !catalogEvidenceValid) || evidence?.fallbackUsed !== false) {
    errors.push("premium_ai_evidence_missing");
  }
  errors.push(...validateDiscoveryCatalogReportProvenance(report));
  if (catalogEvidenceValid && report?.analysisMetadata?.catalogProvenance) {
    try {
      const selection = validateDiscoveryMechanismSelection(report.analysisMetadata.catalogProvenance.selection);
      const assembled = assembleDiscoveryMechanismSelection(selection);
      for (const domain of DISCOVERY_PREMIUM_DOMAINS) {
        const validation = validateDiscoverySectionContent(
          assembled.sections[domain],
          safetyPolicy,
          { generationQualityVersion: 2 },
        );
        if (!validation.isValid) {
          errors.push(...validation.reasons.map((reason) => `catalog_section:${domain}:${reason}`));
        }
      }
    } catch (error) {
      errors.push(`catalog_section_validation:${error instanceof Error ? error.message : String(error)}`);
    }
  }
  if (
    safetyEvidence?.version !== 1
    || safetyEvidence?.gatePassed !== true
    || !["none", "history", "current_or_uncertain"].includes(String(safetyEvidence?.tcaMode || ""))
  ) {
    errors.push("safety_evidence_missing");
  }
  const validatedDomains = Array.isArray(evidence?.validatedDomains)
    ? [...evidence.validatedDomains].sort()
    : [];
  const expectedDomains = ["digestion", "energie", "lifestyle", "mindset", "nutrition", "sommeil", "stress", "training"];
  if (JSON.stringify(validatedDomains) !== JSON.stringify(expectedDomains)) {
    errors.push(`validated_domains:${validatedDomains.length}/8`);
  }
  for (const sectionId of expectedSectionIds) {
    if (!sectionById.has(sectionId)) errors.push(`section_missing:${sectionId}`);
  }
  for (const domain of expectedDomains) {
    const domainChars = stripHtml((sectionById.get(domain) as any)?.content || "").length;
    if (domainChars < MIN_DISCOVERY_SECTION_CHARS) {
      errors.push(`premium_section:${domain}:${domainChars}/${MIN_DISCOVERY_SECTION_CHARS}`);
    }
    if (domainChars > MAX_DISCOVERY_SECTION_CHARS) {
      errors.push(`premium_section_max:${domain}:${domainChars}/${MAX_DISCOVERY_SECTION_CHARS}`);
    }
  }

  if (sections.length < DISCOVERY_DELIVERY_MIN_SECTIONS) {
    errors.push(`sections:${sections.length}/${DISCOVERY_DELIVERY_MIN_SECTIONS}`);
  }
  if (weakSections.length > 2) errors.push(`weak_sections:${weakSections.length}`);
  if (totalContent < 14_000) errors.push(`total_content:${totalContent}/14000`);
  if (totalContent > 45_000) errors.push(`total_content_max:${totalContent}/45000`);
  if (typeof report?.globalScore !== "number" || !Number.isFinite(report.globalScore) || report.globalScore < 0 || report.globalScore > 10) {
    errors.push(`global_score:${String(report?.globalScore)}`);
  }
  if (metrics.length !== 8) errors.push(`metrics:${metrics.length}/8`);
  for (const metric of metrics as any[]) {
    if (typeof metric?.value !== "number" || !Number.isFinite(metric.value) || metric.value < 0 || metric.value > 10) {
      errors.push(`metric_value:${metric?.key || metric?.label || "unknown"}`);
    }
    if (!metric?.label) errors.push(`metric_label:${metric?.key || "unknown"}`);
  }
  if (!report?.clientName || /^(profil|client|prenom|utilisateur)$/i.test(String(report.clientName).trim())) {
    errors.push(`client_name:${String(report?.clientName || "")}`);
  } else {
    const firstNameLower = String(report.clientName).toLowerCase();
    const hasPersonalization = sections.some((s) => stripHtml((s as any).content || "").toLowerCase().includes(firstNameLower));
    if (!hasPersonalization) errors.push(`personalization_missing:${report.clientName}`);
    for (const domain of expectedDomains) {
      const domainText = stripHtml((sectionById.get(domain) as any)?.content || "").toLowerCase();
      if (!domainText.includes(firstNameLower)) errors.push(`domain_personalization_missing:${domain}`);
    }
  }
  if (!report?.generatedAt) errors.push("generated_at_missing");
  if (txt.length < 16_000) errors.push(`report_txt:${txt.length}/16000`);
  if (txt.length > 65_000) errors.push(`report_txt_max:${txt.length}/65000`);
  if (html.length < 30_000 || !/(<!doctype html|<html[\s>])/i.test(html)) errors.push(`report_html:${html.length}/30000`);

  const assembledContent = sections.map((section: any) => stripHtml(section?.content || "")).join("\n");
  const completeVisibleArtifact = [
    report?.clientName || "",
    ...metrics.flatMap((metric: any) => [metric?.label || "", metric?.description || ""]),
    ...sections.flatMap((section: any) => [
      section?.title || "",
      section?.subtitle || "",
      ...(Array.isArray(section?.chips) ? section.chips : []),
      stripHtml(section?.content || ""),
    ]),
    stripHtml(html),
  ].join("\n");
  for (const linguisticError of validateDiscoveryLinguisticQuality(completeVisibleArtifact)) {
    errors.push(`linguistic:${linguisticError}`);
  }
  if (/déficit\s+de\s+sommeil\s+chronique/i.test(completeVisibleArtifact)) {
    errors.push("unsupported_medicalizing_title:sommeil");
  }
  for (const safetyError of validateDiscoverySafetyContent(assembledContent, safetyPolicy).errors) {
    errors.push(`safety:${safetyError}`);
  }
  const metadata = nonRenderedMetadata ?? report?.analysisMetadata ?? {};
  const metadataText = JSON.stringify(metadata);
  const criticalConsistencyText = [completeVisibleArtifact, metadataText]
    .join("\n")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
  const hasCalculatedCriticalBlockage = /\[\s*blocage\s+critique\s*\]/.test(
    criticalConsistencyText,
  );
  const deniesCalculatedCriticalLevel = /\bsans\s+atteindre\s+le\s+niveau\s+critique\s+calcule\b/.test(
    criticalConsistencyText,
  );
  if (hasCalculatedCriticalBlockage && deniesCalculatedCriticalLevel) {
    errors.push("content:critical_level_contradiction");
  }
  const metadataProse = metadata && typeof metadata === "object"
    ? JSON.stringify(Object.fromEntries(
      Object.entries(metadata).filter(([key]) => (
        key !== "questionnaireCoverage" && key !== "catalogProvenance"
      )),
    ))
    : metadataText;
  for (const linguisticError of validateDiscoveryLinguisticQuality(metadataProse)) {
    errors.push(`metadata_linguistic:${linguisticError}`);
  }
  for (const safetyError of validateDiscoverySafetyContent(metadataText, safetyPolicy).errors) {
    errors.push(`metadata_safety:${safetyError}`);
  }
  for (const metadataError of validateDiscoveryNonRenderedMetadata(metadata)) {
    errors.push(`metadata_medicalizing:${metadataError}`);
  }
  if (safetyPolicy.strictEatingSafety && /photos?\s+(?:de\s+)?(?:progression|du\s+physique|du\s+corps)|analyse\s+photo/i.test(assembledContent)) {
    errors.push("safety:tca_progress_photos");
  }

  return { ok: errors.length === 0, errors };
}

/**
 * Final response-bound gate.  Unlike the structural delivery gate, this gate
 * has the immutable questionnaire available and therefore catches factual
 * drift introduced either by the provider or by deterministic report
 * assembly.  It must run immediately before every persistence path.
 */
export function validateDiscoveryReportAgainstResponses(
  report: Partial<ReportData> | null | undefined,
  responses: DiscoveryResponses,
  nonRenderedMetadata?: unknown,
): { ok: boolean; errors: string[] } {
  const sections = Array.isArray(report?.sections) ? report.sections : [];
  const visible = sections
    .map((section) => [
      String(section?.title || ""),
      String(section?.subtitle || ""),
      ...(Array.isArray(section?.chips) ? section.chips.map(String) : []),
      stripInlineHtml(String(section?.content || "")),
    ].join("\n"))
    .join("\n");
  const deterministic = calculateDiscoveryDeterministicProfile(responses);
  const metadataText = JSON.stringify({ nonRenderedMetadata, persisted: report?.analysisMetadata });
  const factualText = `${visible}\n${metadataText}`;
  const errors = validateDiscoveryFactualConsistency(factualText, responses)
    .map((error) => `factual:${error}`);
  const catalogBacked = report?.generationQuality?.version === 2;
  if (catalogBacked) {
    errors.push(...validateDiscoveryCatalogReportProvenance(report).map((error) => `catalog:${error}`));
  }
  const metadata = nonRenderedMetadata && typeof nonRenderedMetadata === "object"
    ? nonRenderedMetadata as Record<string, unknown>
    : report?.analysisMetadata && typeof report.analysisMetadata === "object"
      ? report.analysisMetadata as Record<string, unknown>
      : {};
  const calculatedCriticalCount = deterministic.blocages.filter(
    (blocage) => String(blocage?.severity || "").toLowerCase() === "critique",
  ).length;
  const normalizedVisible = normalizeDiscoveryFactText(visible);
  const criticalDenialPattern = /\b(?:aucun|sans)\s+(?:blocage|axe|niveau|point|signal|element|priorite)[^.!?]{0,30}\bcritique\b|\bsans\s+atteindre\s+le\s+niveau\s+critique\b/g;
  const deniesCritical = criticalDenialPattern.test(normalizedVisible);
  criticalDenialPattern.lastIndex = 0;
  const positiveCriticalText = normalizedVisible.replace(criticalDenialPattern, " ");
  const claimsCritical = /\b(?:blocage|priorite|axe)\s+critique\b|\[\s*(?:blocage\s+)?critique\s*\]/.test(positiveCriticalText);
  if (calculatedCriticalCount === 0 && claimsCritical) {
    errors.push("cross_section:critical_claim_without_calculation");
  }
  if (calculatedCriticalCount > 0 && deniesCritical) {
    errors.push("cross_section:critical_denial_with_calculation");
  }
  const expectedGlobal = Math.round((deterministic.globalScore / 10) * 10) / 10;
  if (Number(report?.globalScore) !== expectedGlobal) {
    errors.push(`score:global:${String(report?.globalScore)}/${expectedGlobal}`);
  }
  const metrics = Array.isArray(report?.metrics) ? report.metrics : [];
  const expectedMetrics = DISCOVERY_PREMIUM_DOMAINS.map((domain) => ({
    key: domain,
    label: DOMAIN_CONFIG[domain].label,
    value: Math.round((deterministic.scoresByDomain[domain] / 10) * 10) / 10,
    max: 10,
    description: DOMAIN_CONFIG[domain].description,
  }));
  const actualMetrics = metrics.map((metric) => ({
    key: String(metric?.key || ""),
    label: String(metric?.label || ""),
    value: Number(metric?.value),
    max: Number(metric?.max),
    description: String(metric?.description || ""),
  }));
  if (JSON.stringify(actualMetrics) !== JSON.stringify(expectedMetrics)) {
    errors.push("score:deterministic_metrics_mismatch");
  }
  const metadataBlocages = Array.isArray(metadata.blocages)
    ? metadata.blocages as Array<Record<string, unknown>> : [];
  if (stableDiscoveryCatalogJson(metadataBlocages) !== stableDiscoveryCatalogJson(deterministic.blocages)) {
    errors.push("metadata:deterministic_blockages_mismatch");
  }
  const expectedCta = buildDiscoveryDeterministicCta(deterministic.blocages, deterministic.safetyPolicy);
  if (String(metadata.ctaMessage || "") !== expectedCta) {
    errors.push("metadata:deterministic_cta_mismatch");
  }
  if (stableDiscoveryCatalogJson(metadata.questionnaireCoverage)
    !== stableDiscoveryCatalogJson(deterministic.questionnaireCoverage)) {
    errors.push("metadata:questionnaire_coverage_mismatch");
  }
  if (nonRenderedMetadata !== undefined
    && JSON.stringify(nonRenderedMetadata) !== JSON.stringify(report?.analysisMetadata)) {
    errors.push("metadata:persisted_external_mismatch");
  }
  const expectedDomainOrder = [...DISCOVERY_PREMIUM_DOMAINS].sort((a, b) => (
    deterministic.scoresByDomain[a] - deterministic.scoresByDomain[b]
    || DISCOVERY_PREMIUM_DOMAINS.indexOf(a) - DISCOVERY_PREMIUM_DOMAINS.indexOf(b)
  ));
  const expectedSectionOrder = ["intro", "global", ...expectedDomainOrder, "scans", "coaching"];
  const actualSectionOrder = sections.map((section) => String(section?.id || ""));
  if (JSON.stringify(actualSectionOrder) !== JSON.stringify(expectedSectionOrder)) {
    errors.push("sections:deterministic_order_mismatch");
  }
  // v2 prose is assembled locally from the immutable, hash-bound catalogue.
  // Its exact render/provenance gate above replaces the obsolete free-prose
  // parser. Legacy v1 reports retain that parser until they are regenerated.
  if (!catalogBacked) {
    const deterministicBlockageTitles = new Set(deterministic.blocages.map((blocage) => blocage.title));
    const providerProse = sections
      .filter((section) => String(section?.id || "") === "global"
        || DISCOVERY_PREMIUM_DOMAINS.includes(String(section?.id || "") as any))
      .flatMap((section) => {
        const paragraphs = String(section?.content || "").match(/<p\b[^>]*>[\s\S]*?<\/p>/gi) || [];
        return paragraphs.map((paragraph) => stripInlineHtml(paragraph)).filter((paragraph) => {
          if (String(section?.id || "") === "global") return true;
          return !/^.+, ton score\s*:/i.test(paragraph)
            && !/^Observations déclarées\s*:/i.test(paragraph)
            && !deterministicBlockageTitles.has(paragraph.trim());
        });
      })
      .join("\n");
    for (const mechanismError of validateDiscoveryMechanismProse(providerProse)) {
      errors.push(`content:${mechanismError}`);
    }
  }
  const qualitySafety = report?.generationQuality?.safety;
  const expectedSafety = {
    version: 1,
    tcaMode: deterministic.safetyPolicy.tcaMode,
    bodyCheckingSignal: deterministic.safetyPolicy.bodyCheckingSignal,
    strictEatingSafety: deterministic.safetyPolicy.strictEatingSafety,
    gatePassed: true,
  };
  if (stableDiscoveryCatalogJson(qualitySafety) !== stableDiscoveryCatalogJson(expectedSafety)) {
    errors.push("safety:deterministic_metadata_mismatch");
  }
  if (catalogBacked && report?.analysisMetadata?.catalogProvenance) {
    try {
      const provenance = report.analysisMetadata.catalogProvenance;
      const selection = validateDiscoveryMechanismSelection(provenance.selection);
      const assembled = assembleDiscoveryMechanismSelection(selection);
      const expectedReport = convertToNarrativeReport({
        globalScore: deterministic.globalScore,
        scoresByDomain: deterministic.scoresByDomain,
        blocages: deterministic.blocages,
        synthese: assembled.synthesis,
        sectionContents: assembled.sections,
        ctaMessage: expectedCta,
        knowledgePreflight: { synthesis: "", domains: {} },
        safetyPolicy: deterministic.safetyPolicy,
        questionnaireCoverage: deterministic.questionnaireCoverage,
        catalogProvenance: provenance,
      }, responses, { generatedAt: String(report.generatedAt || "") });
      const normalizeForDeterministicSeal = (value: Partial<ReportData>): Partial<ReportData> => {
        const cloned = structuredClone(value);
        if (cloned && typeof cloned === "object" && "validationResult" in cloned) {
          const validationResult = (cloned as Record<string, unknown>).validationResult;
          if (validationResult && typeof validationResult === "object" && !Array.isArray(validationResult)) {
            const { deliveryGate: _deliveryGate, ...sealedValidationResult } = validationResult as Record<string, unknown>;
            if (Object.keys(sealedValidationResult).length === 0) {
              delete (cloned as Record<string, unknown>).validationResult;
            } else {
              (cloned as Record<string, unknown>).validationResult = sealedValidationResult;
            }
          }
        }
        return cloned;
      };
      if (stableDiscoveryCatalogJson(normalizeForDeterministicSeal(report))
        !== stableDiscoveryCatalogJson(normalizeForDeterministicSeal(expectedReport))) {
        errors.push("report:catalog_deterministic_reconstruction_mismatch");
      }
    } catch (error) {
      errors.push(`report:catalog_deterministic_reconstruction_failed:${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return { ok: errors.length === 0, errors: [...new Set(errors)] };
}

/**
 * Canonical persistence boundary. Callers must execute this after locking the
 * audit row and pass the row's responses, never a preflight snapshot.
 */
export function validateDiscoveryPersistenceContract(input: {
  narrativeReport: unknown;
  scores: unknown;
  txt: string;
  html: string;
  responses: DiscoveryResponses;
}): { ok: boolean; errors: string[] } {
  const errors = validateDiscoveryQuestionnaireContract(input.responses);
  if (!input.narrativeReport || typeof input.narrativeReport !== "object") {
    return { ok: false, errors: [...errors, "persistence:narrative_report_invalid"] };
  }
  const report = input.narrativeReport as ReportData;
  const deterministic = calculateDiscoveryDeterministicProfile(input.responses);
  const expectedScores = { ...deterministic.scoresByDomain, global: deterministic.globalScore };
  if (JSON.stringify(input.scores) !== JSON.stringify(expectedScores)) {
    errors.push("persistence:deterministic_scores_mismatch");
  }
  if (String(report.clientName || "") !== getDiscoveryFirstName(deterministic.normalized)) {
    errors.push("persistence:client_name_mismatch");
  }
  const canonicalAssets = buildDiscoveryReportAssets(report);
  if (canonicalAssets.txt !== input.txt) errors.push("persistence:canonical_txt_mismatch");
  if (canonicalAssets.html !== input.html) errors.push("persistence:canonical_html_mismatch");
  errors.push(...validateDiscoveryReportForDelivery(
    report,
    { txt: input.txt, html: input.html },
    report.analysisMetadata,
  ).errors.map((error) => `persistence:${error}`));
  errors.push(...validateDiscoveryReportAgainstResponses(
    report,
    deterministic.normalized,
    report.analysisMetadata,
  ).errors.map((error) => `persistence:${error}`));
  return { ok: errors.length === 0, errors: [...new Set(errors)] };
}

export function parseStoredDiscoveryTxt(txt: string): ReportData | null {
  const normalizedTxt = String(txt || "").replace(/\r/g, "").trim();
  if (!normalizedTxt.startsWith("DISCOVERY_REPORT_V1")) return null;

  const clientName = normalizedTxt.match(/^CLIENT_NAME:\s*(.+)$/m)?.[1]?.trim() || "Profil";
  const generatedAt = normalizedTxt.match(/^GENERATED_AT:\s*(.+)$/m)?.[1]?.trim() || new Date().toISOString();
  const globalScore = Number(normalizedTxt.match(/^GLOBAL_SCORE:\s*([0-9.]+)$/m)?.[1] || "0");
  const qualityMode = normalizedTxt.match(/^QUALITY_MODE:\s*(.+)$/m)?.[1]?.trim();
  const qualityVersion = Number(normalizedTxt.match(/^QUALITY_VERSION:\s*([0-9]+)$/m)?.[1] || "0");
  const qualityProvider = normalizedTxt.match(/^QUALITY_PROVIDER:\s*(.+)$/m)?.[1]?.trim();
  const fallbackUsed = normalizedTxt.match(/^FALLBACK_USED:\s*(.+)$/m)?.[1]?.trim();
  const safetyVersion = Number(normalizedTxt.match(/^SAFETY_VERSION:\s*([0-9]+)$/m)?.[1] || "0");
  const safetyTcaMode = normalizedTxt.match(/^SAFETY_TCA_MODE:\s*(.+)$/m)?.[1]?.trim();
  const safetyBodyChecking = normalizedTxt.match(/^SAFETY_BODY_CHECKING:\s*(.+)$/m)?.[1]?.trim();
  const safetyStrictEating = normalizedTxt.match(/^SAFETY_STRICT_EATING:\s*(.+)$/m)?.[1]?.trim();
  const safetyGatePassed = normalizedTxt.match(/^SAFETY_GATE_PASSED:\s*(.+)$/m)?.[1]?.trim();

  const metricsBlock = normalizedTxt.match(/(?:^|\n)METRICS\n([\s\S]*?)\n\nSECTIONS(?:\n|$)/);
  const metrics: Metric[] = metricsBlock
    ? metricsBlock[1]
        .split("\n")
        .map((line) => line.trim())
        .filter((line) => line.startsWith("- "))
        .map((line) => line.slice(2).split("|"))
        .map((parts) => ({
          key: (parts[0] || "").trim(),
          label: (parts[1] || parts[0] || "").trim(),
          value: Number((parts[2] || "0").trim()) || 0,
          max: Number((parts[3] || "10").trim()) || 10,
          description: (parts[4] || "").trim(),
        }))
    : [];

  const sections: SectionContent[] = [];
  const sectionsIndex = normalizedTxt.indexOf("\nSECTIONS\n");
  if (sectionsIndex >= 0) {
    const sectionsBlock = normalizedTxt.slice(sectionsIndex + "\nSECTIONS\n".length).trim();
    const chunks = sectionsBlock
      .split(/^===\s*/m)
      .map((chunk) => chunk.trim())
      .filter(Boolean);

    for (const chunk of chunks) {
      const headerEnd = chunk.indexOf("===");
      if (headerEnd === -1) continue;
      const header = chunk.slice(0, headerEnd).trim();
      const contentText = chunk.slice(headerEnd + 3).trim();
      const [id = "", title = "", subtitle = "", chipsRaw = ""] = header.split("|");
      sections.push({
        id: id.trim(),
        title: title.trim(),
        subtitle: subtitle.trim() || undefined,
        chips: chipsRaw
          .split("~")
          .map((chip) => chip.trim())
          .filter(Boolean),
        content: contentHtmlFromPlainText(contentText),
      });
    }
  }

  if (sections.length === 0) return null;

  return {
    globalScore: Number.isFinite(globalScore) ? globalScore : 0,
    metrics,
    sections,
    clientName,
    generatedAt,
    auditType: "GRATUIT",
    ...(qualityMode === "premium_ai" && qualityVersion === 1 && qualityProvider === "openai" && fallbackUsed === "false"
      && safetyVersion === 1 && ["none", "history", "current_or_uncertain"].includes(String(safetyTcaMode))
      && safetyGatePassed === "true"
      ? {
          generationQuality: {
            mode: "premium_ai" as const,
            version: 1 as const,
            provider: "openai" as const,
            synthesis: "ai_validated" as const,
            validatedDomains: ["digestion", "energie", "lifestyle", "mindset", "nutrition", "sommeil", "stress", "training"],
            fallbackUsed: false as const,
            safety: {
              version: 1 as const,
              tcaMode: safetyTcaMode as DiscoverySafetyPolicy['tcaMode'],
              bodyCheckingSignal: safetyBodyChecking === "true",
              strictEatingSafety: safetyStrictEating === "true",
              gatePassed: true as const,
            },
          },
        }
      : {}),
  };
}

